T[13969]={"^by (.-)%% \n   1 point  : 6 sec%.\n   2 points: 12 sec%.\n   3 points: 30 sec%.\n   4 points: 36 sec%.\n   5 points: 42 sec%.%s*$","em {{1}}%\n1 ponto: 6 s.\n2 pontos: 12 s.\n3 pontos: 30 s.\n4 pontos: 36 s.\n5 pontos: 42 s."}
