T[21160]={"^Your ranged attacks call down a hail of arrows%.%s*$","Seus ataques à distância Xamã uma chuva de flechas."}
T[21161]={"^Calls in an Orbital Arrow Strike dealing (.-)%% weapon damage%.%s*$","Chama um acerto orbital de flechas causando {{1}}% de dano da arma."}
T[21162]={"^Your next Chain Heal has (.-)%% reduced cast time and loses (.-)%% less healing per jump%.%s*$","Sua próxima Cura em Cadeia tem um tempo de lançamento reduzido em {{1}}% e perde {{2}}% menos cura por salto."}
T[21163]={"^Increases Holy damage done by (.-)%% and reduces physical damage taken by (.-)%%%.%s*$","Aumenta o dano Sagrado causado em {{1}}% e reduz o dano Físico recebido em {{2}}%."}
T[21164]={"^Your next Aimed Shot or Multi%-Shot deal (.-)%% additional damage%.%s*$","Seu próximo Tiro Certo ou Tiro Múltiplo causa {{1}}% de dano adicional."}
T[21165]={"^Increases the melee critical strike chance of the caster by (.-)%%%.%s*$","Aumenta a chance de acerto crítico do conjurador em corpo a corpo em {{1}}%."}
T[21166]={"^Transfers (.-)%% damage taken to the Paladin%.%s*$","Transfere {{1}}% do dano recebido ao Paladino."}
T[21167]={"^Haste and critical strike chance increased by (.-)%%%.%s*$","Aumento dá aceleração e a chance de acerto crítico em {{1}}%."}
T[21168]={"^Increases your Holy spell critical strike chance by (.-)%% for (.-)%.%s*$","Aumenta sua chance de acerto crítico com feitiços Sagrado em {{1}}% durante {{2}}."}
T[21169]={"^High Velocity Munitions cause your shots to fire 30%% faster but deal 10%% less damage%.%s*$","As Munições de Alta Velocidade fazem que seus disparos se lancem 30% mais rápido mais causam 10% menos dano."}
T[21170]={"^Damage done by your Mongoose Bite, Raptor Strike and Counterattack increased by 15%%%.%s*$","O dano de seu Mordedura do Mangusto, acerto Rápido e Contra-ataque aumenta em 15%."}
T[21171]={"^Applies Deadly Poison every 2 seconds%.%s*$","Aplica Veneno Mortal a cada 2 segundos."}
T[21173]={"^Increases the damage of your next Overpower by (.-)%%%. Your next Overpower also grants you (.-) Rage per stack%.%s*$","Aumenta o dano de seu próximo Sobrepoder em {{1}}%. Seu próximo Sobrepoder também concede a você {{2}} Fúria para cada acumulação."}
T[21174]={"^Upon reaching three stacks, your next Bloodthirst will deal (.-)%% more damage%.%s*$","Ao alcançar três acúmulos, seu próximo Sanguecirujano causará um dano adicional em {{1}}%."}
T[21175]={"^Increases your melee attack speed by (.-)%%%. While at max stacks, your next Windfury hits 2 additional times and consumes all stacks%.%s*$","Aumenta sua velocidade de ataque em corpo a corpo em {{1}}%. Quando alcanças o máximo de acúmulos, seu próximo Ataque Fúria do Vento golpeia 2 vezes adicionais e consome todos os acúmulos."}
T[21176]={"^Your next Windfury Attack will trigger 2 additional attacks%.%s*$","Seu próximo Ataque Fúria do Vento Acionará 2 ataques adicionais."}
T[21177]={"^Shuriken toss only triggers 0%.5 sec global cooldown%.%s*$","O tiro de shurikens somente ativa a recarga global durante 0,5 s."}
T[21178]={"^Your next Syndicate Sniper Shot does not require stealth, costs (.-) less energy and deals (.-)%% more damage%. Lasts (.-)%.%s*$","Seu próximo Tiro de snipe do Sindicato não requer estar em Furtividade, custa {{1}} menos energia e causa {{2}}% dano adicional. Dura {{3}}."}
T[21179]={"^Reduces the cast time of Soul Fire by (.-) second%.%s*$","Reduz o tempo de lançamento de Fogo d'Alma em {{1}} segundo."}
T[21180]={"^Your Hand of Gul'dan summons twice the amount of Wild Imps%.%s*$","Seu Mão de Gul'dan evocar duplo quantidade Diabrete Selvagens."}
T[21181]={"^Dealt Fire damage recently%.%s*$","Você causou dano de Fogo recentemente."}
T[21182]={"^Dealt Frost damage recently%.%s*$","Você causou dano de Gelo recentemente."}
T[21183]={"^Dealt Nature damage recently%.%s*$","Você causou dano de Natureza recentemente."}
T[21184]={"^Taking (.-)%% more damage from the casters Deadly Poison, Envenom and Instant Poison%.%s*$","recebem {{1}}% dano adicional por parte do Veneno Mortal, Envenenar e Veneno Instantâneo dos lanceiros."}
T[21185]={"^Allows the usage of your next Kill Shot regardless of the target's health state but deals (.-)%% reduced damage if used on target's above 20%% health%.%s*$","Permite o uso de seu próximo Disparo Letal independentemente do estado de vida do alvo, mas causa um dano reduzido em {{1}}% se for usada contra alvos com mais de 20% de vida."}
T[21186]={"^Your next Eviscerate costs (.-) less energy and increases the duration of Rupture by (.-) sec%.%s*$","Seu próximo Eviscerar custa {{1}} menos energia e aumenta a duração de Ruptura em {{2}} s."}
T[21187]={"^Your next Arcane Shot, Quick Shot or Explosive Shot deals (.-)%% increased damage and costs s2%% less mana%.%s*$","Seu próximo Tiro Arcano, Disparo Rápido ou Tiro Explosivo causará dano aumentado em {{1}}% e custará s2% menos mana."}
T[21188]={"^Attack power increased by 1 per (.-) armor%.%s*$","Poder de Ataque aumentado em 1 para cada {{1}} armadura."}
T[21189]={"^While Sprint is active, periodically triggers poison around you%.%s*$","Enquanto dure o Disparada, periodicamente ativa veneno ao seu redor."}
T[21190]={"^Consume 3 stacks to deal (.-) additional Nature damage%s*$","Consumir 3 acúmulos para causar {{1}} de dano adicional de Natureza"}
T[21191]={"^Reduces damage taken from creatures by (.-)%% and Increases healing taken by (.-)%%%.%s*$","Reduz o dano recebido de bichos em {{1}}% e aumenta a cura recebida em {{2}}%."}
