T[21332]={"^|cffFFFFF0Mythic 14%+|r\n\n|cffFF9900Devotion|r\nAttacks dealt by nearby allies deal |cffFF800015%% weapon damage as holy damage|r%.%s*$","|cffFFFFF0Mítico 14+|r\n\n|cffFF9900Devoção|r\nOs ataques realizados por aliados próximos causam |cffFF800015% dano da arma como dano Sagrado|r."}
